import sys,struct,mmap,json
sys.path.insert(0,'.local/crash-tools/pylibs')
from capstone import Cs,CS_ARCH_ARM64,CS_MODE_ARM
path='/Applications/Google Chrome.app/Contents/Frameworks/Google Chrome Framework.framework/Versions/154.0.8037.97/Google Chrome Framework'
f=open(path,'rb');b=mmap.mmap(f.fileno(),0,access=mmap.ACCESS_READ);n=struct.unpack_from('<I',b,16)[0];o=32;segments=[]
for i in range(n):
 cmd,size=struct.unpack_from('<II',b,o)
 if cmd==0x19:
  vm,sz,fo,fs=struct.unpack_from('<QQQQ',b,o+24);segments.append((vm,sz,fo,fs))
 o+=size
md=Cs(CS_ARCH_ARM64,CS_MODE_ARM)
frames=json.load(open('.local/smart-shorts-seven/latest-crash.json'))['threads'][0]['frames'][:9]
for fr in frames:
 addr=int(fr['module_offset'],16);start=addr-24
 for vm,sz,fo,fs in segments:
  if vm<=start<vm+fs:
   raw=b[fo+start-vm:fo+start-vm+64];print('FRAME',fr['frame'],hex(addr));
   for ins in md.disasm(raw,start):print(hex(ins.address),ins.mnemonic,ins.op_str)
PY
python3 .local/smart-shorts-seven/disassemble-crash.py
